# Proposal: fix 1 for add-vat

## Why
The verifier found problems in `add-vat` that this change fixes. The findings are listed below with their ids; each task of this change names the ones it answers.

## What Changes
- F-366420f0 (major): VAT ignores any applied discount code: total_with_vat starts from self.subtotal() and never uses the discounted total that Cart.total() computes. If a discount code has been applied, the VAT total is worked out on the pre-discount amount, so a customer would pay VAT on money they were not charged. The proposal says 'the cart total shown to the customer includes VAT', but the requirement says 'cart subtotal plus VAT', and no scenario covers a discounted cart. Two reasonable implementations give different answers. Example: with 10% off and RO, the committed code gives 121.00, while VAT on the discounted total gives 108.90. [reject...

## Impact
The code and the tests of `add-vat`.
# Spec Delta

## Purpose
VAT is added to the cart total according to the customer's country so that invoices show the right amount.

## ADDED Requirements

### Requirement: VAT by country — regression 1
The behaviour pinned by the scenarios below SHALL hold.

#### Scenario: VAT ignores any applied discount code
- **WHEN** a 10 % discount code is applied to a RO cart with subtotal 100.00
- **THEN** total_with_vat is 108.90
from decimal import Decimal


class UnsupportedCountry(ValueError):
    """Raised when a VAT rate is requested for an unsupported country."""


_VAT_RATES = {
    "RO": Decimal("0.21"),
    "DE": Decimal("0.19"),
}


def vat_rate(country: str) -> Decimal:
    try:
        return _VAT_RATES[country]
    except KeyError as error:
        raise UnsupportedCountry(f"Unsupported country: {country}") from error
from __future__ import annotations

from dataclasses import dataclass, field
from decimal import ROUND_HALF_UP, Decimal

from pricing.discounts import AmountOff, DiscountRegistry, PercentOff
from pricing.vat import vat_rate


@dataclass(frozen=True)
class LineItem:
    sku: str
    unit_price: Decimal
    quantity: int = 1

    def __post_init__(self) -> None:
        if self.quantity < 1:
            raise ValueError("quantity must be at least 1")
        if self.unit_price < 0:
            raise ValueError("unit_price must not be negative")

    @property
    def total(self) -> Decimal:
        return self.unit_price * self.quantity


@dataclass
class Cart:
    items: list[LineItem] = field(default_factory=list)
    _discount: PercentOff | AmountOff | None = field(default=None, init=False, repr=False)

    def add(self, item: LineItem) -> None:
        self.items.append(item)

    def subtotal(self) -> Decimal:
        return sum((item.total for item in self.items), Decimal(0))

    def apply_code(self, code: str, registry: DiscountRegistry) -> None:
        self._discount = registry.lookup(code)

    def total(self) -> Decimal:
        subtotal = self.subtotal()
        discount = self._discount
        if isinstance(discount, PercentOff):
            total = subtotal * (Decimal(1) - discount.percent / Decimal(100))
        elif isinstance(discount, AmountOff):
            total = subtotal - discount.amount
        else:
            total = subtotal

        return max(total, Decimal(0)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

    def total_with_vat(self, country: str) -> Decimal:
        total = self.subtotal() * (Decimal(1) + vat_rate(country))
        return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
from decimal import Decimal

import pytest

from pricing import Cart, LineItem, UnsupportedCountry, vat_rate


@pytest.mark.parametrize(
    ("country", "expected_rate"),
    [("RO", Decimal("0.21")), ("DE", Decimal("0.19"))],
)
def test_vat_rate_is_defined_for_supported_countries(country, expected_rate):
    assert vat_rate(country) == expected_rate


def test_vat_rate_rejects_unsupported_country():
    with pytest.raises(UnsupportedCountry):
        vat_rate("US")


@pytest.mark.parametrize(
    ("country", "expected_total"),
    [("RO", Decimal("121.00")), ("DE", Decimal("119.00"))],
)
def test_cart_total_with_vat_for_supported_countries(country, expected_total):
    cart = Cart([LineItem("item", Decimal("100.00"))])

    assert cart.total_with_vat(country) == expected_total


def test_cart_total_with_vat_rejects_unsupported_country():
    cart = Cart([LineItem("item", Decimal("100.00"))])

    with pytest.raises(UnsupportedCountry):
        cart.total_with_vat("US")
